fn pairwise_addition(a: Vec<i32>) -> Vec<i32> {
    // Ensure the input length is even
    assert!(a.len() % 2 == 0, "Input length must be even");

    // Sum each consecutive pair and collect into a new vector
    a.chunks(2)
     .map(|pair| pair[0] + pair[1])
     .collect()
}

fn main() {
    let input = vec![1, 2, 3, 4, 5, 6];
    let output = pairwise_addition(input);
    assert_eq!(output, vec![3, 7, 11]);
    println!("pairwise sums: {:?}", output);
}